namespace xr_export_gate {
std::mutex mutex;std::condition_variable changed;bool entered=false,released=false;std::atomic<bool> armed=false;
void arm(){std::lock_guard lock(mutex);entered=released=false;armed=true;}
void release(){std::lock_guard lock(mutex);released=true;changed.notify_all();}
bool wait(){std::unique_lock lock(mutex);return changed.wait_for(lock,std::chrono::seconds(60),[]{return entered;});}
struct Guard{~Guard(){release();}};
}
extern "C" int __real_fsync(int);
extern "C" int __wrap_fsync(int fd){auto result=__real_fsync(fd);struct stat s{};if(!result&&!fstat(fd,&s)&&S_ISREG(s.st_mode)&&xr_export_gate::armed.exchange(false)){std::unique_lock lock(xr_export_gate::mutex);xr_export_gate::entered=true;xr_export_gate::changed.notify_all();xr_export_gate::changed.wait(lock,[]{return xr_export_gate::released;});}return result;}
