using namespace dome;unsigned checks=0;using J=nlohmann::json;
void check(bool ok,const char *message){if(!ok)throw std::runtime_error(message);++checks;std::cout<<"PASS "<<message<<std::endl;}
void settled(Document &d){if(!d.wait_input()||!d.wait_native_stroke()||!d.wait_asset()||!d.wait_mesh())throw std::runtime_error("XR export input/worker did not settle");}
std::vector<uint8_t> bytes(const std::filesystem::path&p){std::ifstream f(p,std::ios::binary);return {std::istreambuf_iterator<char>(f),{}};}
uint32_t word(const std::vector<uint8_t>&b,size_t at){return uint32_t(b.at(at))|uint32_t(b.at(at+1))<<8|uint32_t(b.at(at+2))<<16|uint32_t(b.at(at+3))<<24;}
J json(const std::vector<uint8_t>&b){return J::parse(b.begin()+20,b.begin()+20+word(b,12));}
uint32_t network_word(const std::vector<uint8_t>&b,size_t at){return uint32_t(b.at(at))<<24|uint32_t(b.at(at+1))<<16|uint32_t(b.at(at+2))<<8|b.at(at+3);}
uint32_t portable_resolution(const std::vector<uint8_t>&data,bool emission=false){const auto j=json(data);const auto material=j.at("meshes").at(0).at("primitives").at(0).at("material").get<size_t>();const auto texture=(emission?j.at("materials").at(material).at("emissiveTexture"):j.at("materials").at(material).at("pbrMetallicRoughness").at("baseColorTexture")).at("index").get<size_t>();const auto image=j.at("textures").at(texture).at("source").get<size_t>();const auto view=j.at("images").at(image).at("bufferView").get<size_t>();const auto offset=j.at("bufferViews").at(view).value("byteOffset",size_t{});const size_t bin=20+word(data,12)+8;check(data.at(bin+offset)==137&&data.at(bin+offset+1)=='P',"Controller policy emits a genuine PNG core texture");const auto size=network_word(data,bin+offset+16);check(size==network_word(data,bin+offset+20),"Portable controller texture has square declared dimensions");return size;}
